program HitungFungsi
{ Menghitung nilai dari fungsi f(x) = (x^3 + 3x) / (x^4 - 3x^2 + 4) }

KAMUS:
    x    : real    { input nilai x }
    hasil : real    { hasil perhitungan f(x) }

ALGORITMA:
    input(x)

    hasil <- (x * x * x + 3.0 * x) / (x * x * x * x - 3.0 * x * x + 4.0)

    output(hasil)

endprogram

program HitungFungsiY
{ Menghitung nilai dari fungsi y = (x^2 + 1/x)^2 }

KAMUS:
    x : real    { input nilai x }
    y : real    { hasil perhitungan y }

ALGORITMA:
    input(x)

    y <- (x * x + 1.0 / x) * (x * x + 1.0 / x)

    output(y)

endprogram

Program Nilai_Mutlak
{ Membaca bilangan bulat 32 bit n, lalu mencetak |n|
  tanpa percabangan, hanya dengan operasi bilangan bulat }

KAMUS
    n     : integer   { 32 bit }
    m     : integer   { mask tanda }
    hasil : integer

ALGORITMA
    input(n)
    m     ← n shr 31          { 0 jika n >= 0, -1 (semua bit 1) jika n < 0 }
    hasil ← (n xor m) - m
    output(hasil)

