program HitungPecahanKembalian

kamus
    kembalian : integer    { Total uang kembalian }
    sepuluhRibu : integer  { Jumlah lembar Rp 10.000 }
    limaRibu    : integer  { Jumlah lembar Rp 5.000 }
    satuRibu    : integer  { Jumlah lembar Rp 1.000 }
    sisa        : integer  { Sisa uang kembalian setelah diambil pecahan terbesar }

algoritma
    input(kembalian)

    { Hitung pecahan 10.000 }
    sepuluhRibu <- kembalian div 10000
    sisa <- kembalian mod 10000

    { Hitung pecahan 5.000 dari sisa kembalian }
    limaRibu <- sisa div 5000
    sisa <- sisa mod 5000

    { Hitung pecahan 1.000 dari sisa terakhir }
    satuRibu <- sisa div 1000

    output(sepuluhRibu, limaRibu, satuRibu)

endprogram

program KonversiDetikKeWaktu

kamus
    totalDetik : integer    { Total waktu masukan dalam detik }
    jam        : integer    { Hasil konversi jam }
    menit      : integer    { Hasil konversi menit }
    sisaDetik  : integer    { Hasil konversi sisa detik }

algoritma
    read(totalDetik)

    jam <- totalDetik div 3600
    menit <- (totalDetik mod 3600) div 60
    sisaDetik <- totalDetik mod 60

    write(jam, menit, sisaDetik)

endprogram

program Balikbilangan
kamus
   N     : integer    { Bilangan tiga digit masukan }
    d1    : integer    { Digit satuan }
    d2    : integer    { Digit puluhan }
    d3    : integer    { Digit ratusan }
    hasil : integer    { Bilangan setelah dibalik }
algoritma
    input(N)

    d1 <- N mod 10
    d2 <- (N div 10) mod 10
    d3 <- N div 100

    hasil <- (d1 * 100) + (d2 * 10) + d3

    output(hasil)

endprogram

program Cekfaktor
kamus
    x     : integer    { Bilangan pertama }
    y     : integer    { Bilangan kedua }
    sisa  : integer    { Sisa hasil bagi x mod y }
    hasil : integer    { 1 jika y faktor dari x, 0 jika bukan }

algoritma
    input(x, y)

    sisa <- x mod y

    { Mengubah nilai sisa > 0 menjadi 1, dan sisa = 0 tetap 0 }
    { Lalu dibalik nilainya menggunakan 1 - (...) }
    hasil <- 1 - ((sisa + y - 1) div y)

    output(hasil)

endprogram

program CekFaktor

kamus
    x : integer    { Bilangan pertama (lebih besar) }
    y : integer    { Bilangan kedua (pembagi) }
    hasil : integer    { Output: 1 jika y faktor dari x, 0 jika bukan }

algoritma
    input(x, y)

    { Jika x habis dibagi y, x mod y akan bernilai 0. }
    { Menggunakan ekspresi kondisi/relasional untuk menghasilkan 1 (True) atau 0 (False). }
    hasil <- (x mod y = 0)

    output(hasil)

endprogram

program Ceknegatif
kamus
    N     : integer    { Bilangan bulat masukan 32-bit }
    hasil : integer    { Output: 1 jika negatif, 0 jika tidak }

algoritma
    input(N)

    { Karena rentang N adalah -2147483648 s.d. 2147483647 }
    { N + 2147483648 akan bernilai < 2147483648 jika N negatif }
    { dan >= 2147483648 jika N non-negatif }
    hasil <- 1 - ((N + 2147483648) div 2147483648)

    output(hasil)

endprogram

program CekNegatif

kamus
    N     : integer    { Bilangan bulat masukan 32-bit }
    hasil : integer    { Output: 1 jika negatif, 0 jika tidak }

algoritma
    input(N)

    { Dalam format 32-bit signed integer (Two's Complement): }
    { Bit paling kiri (bit ke-31 / MSB) adalah sign bit: }
    { - Nilai 1 menandakan bilangan negatif }
    { - Nilai 0 menandakan bilangan non-negatif (nol/positif) }
    { Menggeser bit ke kanan sebanyak 31 posisi dengan 'logical shift' }
    { atau melakukan pergeseran aritmatika lalu dikandandkan dengan 1 }

    hasil <- (N bit-shift-right 31) bit-and 1

    output(hasil)

endprogram

program Nilaimutlak32bit

kamus
    x     : integer    { Bilangan bulat masukan (32-bit) }
    mask  : integer    { Topeng bitwise dari bit tanda/sign bit }
    hasil : integer    { Nilai mutlak dari N }

algoritma
    input(x)

    { Menggeser bit sebanyak 31 posisi ke kanan untuk mengambil bit tanda (sign bit). }
    { Jika N positif, mask = 0 (semua bit 0). }
    { Jika N negatif, mask = -1 (semua bit 1 / dua komplemen). }
    mask <- N bit-shift-right 31

    { Menggunakan properti XOR dan pengurangan: }
    { Jika N >= 0: (N XOR 0) - 0 = N }
    { Jika N < 0 : (N XOR -1) - (-1) = NOT(N) + 1 = -N }
    hasil <- (N bit-xor mask) - mask

    output(hasil)

endprogram

program NilaiMutlak32Bit

kamus
    N     : integer    { Bilangan bulat masukan (32-bit) }
    mask  : integer    { Topeng bitwise dari bit tanda/sign bit }
    hasil : integer    { Nilai mutlak dari N }

algoritma
    read(N)

    { Menggeser bit sebanyak 31 posisi ke kanan untuk mengambil bit tanda (sign bit). }
    { Jika N positif, mask = 0 (semua bit 0). }
    { Jika N negatif, mask = -1 (semua bit 1 / dua komplemen). }
    mask <- N bit-shift-right 31

    { Menggunakan properti XOR dan pengurangan: }
    { Jika N >= 0: (N XOR 0) - 0 = N }
    { Jika N < 0 : (N XOR -1) - (-1) = NOT(N) + 1 = -N }
    hasil <- (N bit-xor mask) - mask

    write(hasil)

endprogram

program Menyisipkanangkatengah

kamus
    bilangan : integer    { Bilangan empat digit masukan, contoh: 1234 }
    disisip  : integer    { Bilangan satu digit yang akan disisipkan, contoh: 5 }
    depan    : integer    { Dua digit bagian depan, contoh: 12 }
    belakang : integer    { Dua digit bagian belakang, contoh: 34 }
    hasil    : integer    { Bilangan lima digit hasil penggabungan }

algoritma
    input(bilangan, disisip)

    { Mengambil 2 digit depan dengan membagi bulat 100 }
    depan <- bilangan div 100

    { Mengambil 2 digit belakang dengan sisa bagi (mod) 100 }
    belakang <- bilangan mod 100

    { Menyusun kembali: (depan * 1000) + (disisip * 100) + belakang }
    hasil <- (depan * 1000) + (disisip * 100) + belakang

    output(hasil)

endprogram

program Tukartigavariabel

kamus
    x    : integer    { Variabel x }
    y    : integer    { Variabel y }
    z    : integer    { Variabel z }
    temp : integer    { Variabel penampung sementara }

algoritma
    input(x, y, z)

    { Menyimpan nilai asal y ke variabel sementara }
    temp <- y

    { Variabel y diisi nilai asal x }
    y <- x

    { Variabel x diisi nilai asal z }
    x <- z

    { Variabel z diisi nilai asal y (yang tersimpan di temp) }
    z <- temp

    output(x, y, z)

endprogram

