package  main

import "fmt"

func main () {
    var totaldetik int
    // menerima masukan dari pengguna
    fmt.print("masukan waktu lari(detik): ")
    err:= fmt.Scanln(&totaldetik)

    // validasi input untuk mastikan bilangan bulat positif
    if err := nil totaldetik < 0 {
            fmt.Println("masukan harus bilangan bulat  positif")
            return
    }
    jam:= totaldetik / 3600
    sisadetik:= totaldetik % 3600
    menit:= sisadetik / 60
    detik:= sisadetik % 60
    fmt.Println(jam,"jam,","menit","detik")
}

