Algoritma Kalkulator_Pecahan

DEKLARASI:
    a, b, c, d : integer { Input pembilang dan penyebut }
    x, y       : integer { Variabel untuk menyimpan hasil pembilang dan penyebut }

ALGORITMA:
    // 1. Membaca masukan dari pengguna
    baca(a, b, c, d)

    // 2. Operasi Penjumlahan (a/b + c/d)
    x = (a * d) + (b * c)
    y = b * d
    tulis("Penjumlahan: ", x, "/", y)

    // 3. Operasi Pengurangan (a/b - c/d)
    x = (a * d) - (b * c)
    y = b * d
    tulis("Pengurangan: ", x, "/", y)

    // 4. Operasi Perkalian (a/b * c/d)
    x = a * c
    y = b * d
    tulis("Perkalian: ", x, "/", y)

    // 5. Operasi Pembagian (a/b : c/d = a/b * d/c)
    x = a * d
    y = b * c
    tulis("Pembagian: ", x, "/", y)

