ALGORITMA NilaiMutlakTanpaPercabangan

DEKLARASI:
    n : INTEGER (32-bit)
    mask : INTEGER (32-bit)
    abs_val : INTEGER (32-bit)

ALGORITMA:
    input n

    // Geser bit ke kanan sebanyak 31 kali untuk mendapatkan bit tanda (sign bit)
    // Jika n negatif, mask akan berisi -1 (semua bit 1)
    // Jika n positif atau 0, mask akan berisi 0 (semua bit 0)
    mask <- n BITWISE_RIGHT_SHIFT 31

    // Terapkan rumus bitwise untuk mencari nilai mutlak:
    // (n XOR mask) - mask
    abs_val <- (n BITWISE_XOR mask) - mask

    output abs_val

