    var a, b, c, d int
    fmt.Scan(&a, &b, &c, &d)

    // Penjumlahan
    tambahX := a*d + b*c
    tambahY := b * d

    // Pengurangan
    kurangX := a*d - b*c
    kurangY := b * d

    // Perkalian
    kaliX := a * c
    kaliY := b * d

    // Pembagian
    bagiX := a * d
    bagiY := b * c

    // Tampilan sederhana tanpa %d
    fmt.Println("Penjumlahan:", tambahX, "/", tambahY)
    fmt.Println("Pengurangan:", kurangX, "/", kurangY)
    fmt.Println("Perkalian:", kaliX, "/", kaliY)
    fmt.Println("Pembagian:", bagiX, "/", bagiY)
}

