program nilai_mutlak
kamus
    x, mask, hasil: integer
algoritma
    // Membaca masukan bilangan bulat 32-bit
    input(x)

    // Mendapatkan mask (bernilai -1 jika x negatif, 0 jika positif/nol)
    mask = x div 2147483648  // atau menggunakan bitwise shift: mask = x >> 31

    // Menggunakan operasi aritmatika dan bitwise untuk nilai mutlak tanpa if
    hasil = (x + mask) xor mask

    // Menampilkan hasil nilai mutlak
    output(hasil)
endprogram

program tukar_variabel
kamus
    x, y, z, temp: integer
algoritma
    // Membaca masukan nilai x, y, dan z
    input(x, y, z)

    // Menyimpan sementara nilai x agar tidak hilang saat ditimpa
    temp = x

    // Melakukan pertukaran nilai sesuai aturan soal:
    // 1. Variabel y berisi nilai dari x
    // 2. Variabel x berisi nilai dari z
    // 3. Variabel z berisi nilai dari y (menggunakan nilai awal x yang disimpan di temp)
    x = z
    z = y
    y = temp

    // Menampilkan hasil akhir variabel x, y, dan z secara berurutan
    output(x)
    output(y)
    output(z)
endprogram

