ALGORITMA Sisa_Cookies_Keluarga_Ma

DEKLARASI:
    y    : integer  { jumlah cookies }
    x    : integer  { jumlah anggota keluarga }
    sisa : integer  { sisa cookies untuk anak bungsu }

