ALGORITMA Periksa_Negatif_32Bit

DEKLARASI:
    bilangan : integer  { Bilangan bulat 32-bit yang diperiksa }
    hasil    : integer  { Output berupa 1 atau 0 }

DESKRIPSI:
    BACA bilangan

    { Geser bit ke kanan secara logis sebanyak 31 bit untuk mengambil bit tanda }
    hasil ← bilangan >>> 31

    TULIS hasil

ALGORITMA Nilai_Mutlak_Tanpa_Kondisional

DEKLARASI:
    x      : integer  { bilangan bulat 32-bit }
    mask   : integer  { bit tanda }
    mutlak : integer  { hasil nilai mutlak }

DESKRIPSI:
    BACA x

    { Membuat mask: menghasilkan 0 jika positif, -1 jika negatif }
    mask ← x >> 31

    { Menghitung nilai mutlak dengan operasi bitwise XOR dan pengurangan }
    mutlak ← (x XOR mask) - mask

    TULIS mutlak

ALGORITMA Sisip_Angka_Tengah

DEKLARASI:
    bilangan   : integer  { bilangan 4 digit }
    sisipan    : integer  { angka 1 digit yang disisipkan }
    depan      : integer  { menampung 2 digit depan }
    belakang   : integer  { menampung 2 digit belakang }
    hasil_baru : integer  { hasil akhir setelah penyisipan }

DESKRIPSI:
    BACA bilangan, sisipan

    { Memecah bilangan menjadi dua bagian }
    depan    ← bilangan DIV 100
    belakang ← bilangan MOD 100

    { Menyisipkan angka baru dan menggabungkannya kembali }
    hasil_baru ← (depan * 1000) + (sisipan * 100) + belakang

    TULIS hasil_baru

ALGORITMA TigaVariabel
KAMUS
    x, y, z, temp: integer
DESKRIPSI
    input(x, y, z)
    temp ← y        { simpan nilai y }
    y ← x           { y berisi nilai x }
    x ← z           { x berisi nilai z }
    z ← temp        { z berisi nilai y semula }
    output(x, y, z)

ALGORITMA Balik_Bilangan_Tiga_Digit

DEKLARASI:
    N : integer       { Variabel untuk menyimpan input asli }
    ratusan : integer { Variabel untuk digit pertama }
    puluhan : integer { Variabel untuk digit kedua }
    satuan : integer  { Variabel untuk digit ketiga }
    hasil : integer   { Variabel untuk menyimpan hasil akhir }

DESKRIPSI:
    { 1. Membaca input sebagai satu bilangan bulat }
    READ N

    { 2. Memisahkan digit menggunakan operasi matematika }
    ratusan ← N div 100
    puluhan ← (N div 10) mod 10
    satuan  ← N mod 10

    { 3. Menyusun kembali menjadi satu bilangan bulat terbalik }
    hasil ← (satuan * 100) + (puluhan * 10) + ratusan

    { 4. Menampilkan hasil }
    WRITE hasil

