    DEKLARASI:
        x : integer {input 1}
        y : integer {input 2}
        z : integer {input 3}
        w : integer {input 4}
        Hasil : integer {Hasil penjumlahan}
    ALGORITMA:
        INPUT x, y, z, w
        Hasil <- x + y + z + w
        OUTPUT Hasil
endprogram

program SISA_COOKIES

kamus
    y : integer {jumlah cookies}
    x : integer {jumlah keluarga}
    Cookies : integer {sisa cookies}

algoritma
    input y, x
    Cookies <- y mod x
    output Cookies
endprogram

program CekNegatif

kamus
    n : integer { bilangan 32-bit }
    hasil : integer

algoritma
    read(n)

    // Geser bit ke kanan sebanyak 31 posisi (bit shifting)
    // Pada representasi Complement-2, bit paling kiri (bit sign) bernilai 1 jika negatif
    // Dan menggunakan bitwise AND 1 untuk mengambil nilai bit tersebut
    hasil <- (n bitrshift 31) bitand 1

    write(hasil)
endprogram

program TukarTigaVariabel

kamus
    x, y, z : integer
    temp : integer

algoritma
    // Membaca masukan x, y, z dalam urutan ini
    read(x, y, z)

    // Simpan nilai awal x ke variabel sementara
    temp <- x

    // Lakukan penukaran
    x <- z
    y <- temp
    z <- y  // Catatan: Karena y sekarang berisi nilai awal x, maka z mengambil nilai awal y
            // Namun agar lebih aman/jelas secara berurutan:
            // temp menyimpan x_lama
            // x mengambil z_lama
            // y mengambil x_lama (temp)
            // z mengambil y_lama (kita butuh simpan y_lama dulu jika di-overwrite)
endprogram

PROGRAM TukarDigit
{
  I.S. : Pengguna memasukkan sebuah bilangan bulat positif 3 digit (bilangan).
  F.S. : Menampilkan bilangan baru dengan posisi digit yang dibalik (satuan menjadi ratusan, ratusan menjadi satuan).
}

KAMUS
  bilangan, ratusan, puluhan, satuan, hasil_balik : integer

ALGORITMA:
  // 1. Membaca masukan dari pengguna sebagai satu bilangan bulat
  read(bilangan)

  // 2. Mengambil digit ratusan (contoh: 123 / 100 = 1)
  ratusan <- bilangan div 100

  // 3. Mengambil digit puluhan (contoh: (123 mod 100) / 10 = 2)
  puluhan <- (bilangan mod 100) div 10

  // 4. Mengambil digit satuan (contoh: 123 mod 10 = 3)
  satuan <- bilangan mod 10

  // 5. Menyusun kembali digit dalam urutan terbalik (satuan*100 + puluhan*10 + ratusan*1)
  hasil_balik <- (satuan * 100) + (puluhan * 10) + ratusan

  // 6. Menampilkan keluaran sebagai satu bilangan bulat
  write(hasil_balik)
ENDPROGRAM

package main

import "fmt"

func main() {
	var n int32

	// Membaca input bilangan bulat 32-bit
	fmt.Scan(&n)

	// Menggeser bit sebanyak 31 ke kanan untuk mengambil sign bit,
	// kemudian di-AND dengan 1
	hasil := (uint32(n) >> 31) & 1

	fmt.Println(hasil)
}
